```

## Handler logic

```ts
import { createHash } from "node:crypto";
import type { Request, Response } from "express";
import type { Pool, PoolClient } from "pg";

const STALE_LOCK_SECONDS = 120; // must exceed your max request duration
const KEY_MAX_LENGTH = 255;

export interface WorkResult {
  status: number;
  body: unknown;
}

class LockLostError extends Error {}

type Claim =
  | { kind: "acquired"; attempt: number }
  | { kind: "replay"; status: number; body: unknown }
  | { kind: "in_progress" }
  | { kind: "mismatch" };

function hashRequest(req: Request): string {
  // Clients retry with identical bytes, so a plain stringify is stable enough.
  // If other clients may reorder JSON fields, canonicalize before hashing.
  return createHash("sha256")
    .update(`${req.method}\n${req.path}\n${JSON.stringify(req.body ?? null)}`)
    .digest("hex");
}

async function claimKey(
  pool: Pool,
  userId: string,
  key: string,
  hash: string
): Promise<Claim> {
  for (let i = 0; i < 3; i++) {
    // 1. Try to be the first. The primary key makes this atomic.
    const ins = await pool.query(
      `INSERT INTO idempotency_keys (user_id, key, request_hash, status)
       VALUES ($1, $2, $3, 'in_progress')
       ON CONFLICT (user_id, key) DO NOTHING
       RETURNING attempt`,
      [userId, key, hash]
    );
    if (ins.rowCount) return { kind: "acquired", attempt: ins.rows[0].attempt };

    // 2. Key already exists. See what state it's in.
    const { rows } = await pool.query(
      `SELECT request_hash, status, response_code, response_body,
              locked_at < now() - make_interval(secs => $3) AS stale
       FROM idempotency_keys
       WHERE user_id = $1 AND key = $2`,
      [userId, key, STALE_LOCK_SECONDS]
    );
    const row = rows[0];
    if (!row) continue; // deleted by cleanup between the two statements; retry

    if (row.request_hash !== hash) return { kind: "mismatch" };

    if (row.status === "completed") {
      return { kind: "replay", status: row.response_code, body: row.response_body };
    }

    // 3. In progress. If the lock looks abandoned, try to take it over.
    //    The conditional UPDATE guarantees only one caller wins.
    if (row.stale) {
      const took = await pool.query(
        `UPDATE idempotency_keys
         SET attempt = attempt + 1, locked_at = now()
         WHERE user_id = $1 AND key = $2
           AND status = 'in_progress'
           AND locked_at < now() - make_interval(secs => $3)
         RETURNING attempt`,
        [userId, key, STALE_LOCK_SECONDS]
      );
      if (took.rowCount) return { kind: "acquired", attempt: took.rows[0].attempt };
    }

    return { kind: "in_progress" };
  }
  throw new Error("Could not claim idempotency key");
}

export async function withIdempotency(
  pool: Pool,
  req: Request,
  res: Response,
  work: (db: PoolClient) => Promise<WorkResult>
): Promise<void> {
  const key = req.header("Idempotency-Key");
  if (!key || key.length > KEY_MAX_LENGTH) {
    res.status(400).json({ error: "A valid Idempotency-Key header is required" });
    return;
  }

  const userId: string = (req as any).user.id; // scope keys per user
  const claim = await claimKey(pool, userId, key, hashRequest(req));

  switch (claim.kind) {
    case "mismatch":
      res.status(422).json({ error: "Idempotency-Key was already used with a different request" });
      return;
    case "replay":
      res.set("Idempotent-Replayed", "true").status(claim.status).json(claim.body);
      return;
    case "in_progress":
      res.set("Retry-After", "2").status(409).json({ error: "A request with this Idempotency-Key is still in progress" });
      return;
  }

  // We own the key. Do the work and record the response in ONE transaction.
  const { attempt } = claim;
  const db = await pool.connect();
  let result: WorkResult;

  try {
    await db.query("BEGIN");
    result = await work(db);

    // Fencing: only succeeds if nobody took over our lock while we were running.
    const done = await db.query(
      `UPDATE idempotency_keys
       SET status = 'completed', response_code = $3, response_body = $4,
           completed_at = now()
       WHERE user_id = $1 AND key = $2 AND attempt = $5 AND status = 'in_progress'`,
      [userId, key, result.status, JSON.stringify(result.body), attempt]
    );
    if (done.rowCount !== 1) throw new LockLostError();

    await db.query("COMMIT");
  } catch (err) {
    await db.query("ROLLBACK").catch(() => {});

    if (err instanceof LockLostError) {
      // Another attempt took over; our order was rolled back. Let the client retry.
      res.set("Retry-After", "2").status(409).json({ error: "Request superseded by a retry" });
      return;
    }

    // Unexpected failure: release the key so a retry can start fresh.
    await pool
      .query(
        `DELETE FROM idempotency_keys
         WHERE user_id = $1 AND key = $2 AND attempt = $3 AND status = 'in_progress'`,
        [userId, key, attempt]
      )
      .catch(() => {}); // if this fails, the stale-lock takeover covers it
    throw err; // let your normal error middleware produce the 500
  } finally {
    db.release();
  }

  res.status(result.status).json(result.body);
}
```

## Usage

```ts
app.post("/orders", async (req, res) => {
  await withIdempotency(pool, req, res, async (db) => {
    const { rows } = await db.query(
      `INSERT INTO orders (user_id, sku, qty) VALUES ($1, $2, $3) RETURNING *`,
      [(req as any).user.id, req.body.sku, req.body.qty]
    );
    return { status: 201, body: rows[0] };
  });
});
```

## Behavior summary

| Situation | Response |
|---|---|
| No or oversized key | 400 |
| First time seeing the key | runs, stores the response, returns it |
| Same key, same payload, completed | stored status and body, plus `Idempotent-Replayed: true` |
| Same key, different payload | 422 |
| Same key, original still running | 409 with `Retry-After` |
| Same key, original crashed (lock older than 120s) | a retry takes over and runs |
| Unexpected exception | key deleted, error propagates, retry starts fresh |

## Things to be aware of

- **Whatever `work` returns is stored and replayed, including 4xx results** like "out of stock". Thrown exceptions are not stored. If you'd rather not replay validation errors, validate before calling `withIdempotency`.
- **`STALE_LOCK_SECONDS` must be longer than your slowest legitimate request.** The `attempt` fencing token stops a slow-but-alive original from committing after a takeover, but you'd still rather not trigger takeovers needlessly. Set a server request timeout below it.
- **The transaction only protects database writes.** If `work` also calls a payment provider or sends an email, those can't be rolled back, and a takeover could repeat them. Pass the idempotency key downstream (Stripe accepts one) or record external side effects in the same transaction as an outbox row.
- **Only the status code and body are replayed, not headers.** If clients depend on `Location`, store and restore it too.
- **The cleanup job doesn't need changes.** It deletes by `created_at`, and the stale-lock logic now handles abandoned `in_progress` rows long before then.

I can also write tests for the concurrency cases (two simultaneous requests with the same key, and a takeover during a slow request), since those are the paths most likely to hide bugs.

