## Handler

```ts
import { createHash } from "node:crypto";
import type { Request, RequestHandler } from "express";
import { Pool } from "pg";

const STALE_AFTER = "2 minutes"; // must exceed your slowest order-creation request
const KEY_RE = /^[A-Za-z0-9_-]{16,128}$/;

type Result = { status: number; body: unknown };

type Claim =
  | { kind: "owned" }
  | { kind: "replay"; code: number; body: unknown }
  | { kind: "mismatch" }
  | { kind: "in_flight" };

function hashRequest(req: Request): string {
  return createHash("sha256")
    .update(`${req.method}\n${req.originalUrl}\n${JSON.stringify(req.body ?? null)}`)
    .digest("hex");
}

async function claim(pool: Pool, userId: string, key: string, hash: string): Promise<Claim> {
  for (let attempt = 0; attempt < 3; attempt++) {
    // 1. Try to be the first. This is the atomic step that prevents races.
    const ins = await pool.query(
      `INSERT INTO idempotency_keys (user_id, key, request_hash, status)
       VALUES ($1, $2, $3, 'in_progress')
       ON CONFLICT (user_id, key) DO NOTHING`,
      [userId, key, hash]
    );
    if (ins.rowCount === 1) return { kind: "owned" };

    // 2. Someone got there first. See what state they left it in.
    const { rows } = await pool.query(
      `SELECT request_hash, status, response_code, response_body,
              locked_at < now() - $3::interval AS stale
       FROM idempotency_keys WHERE user_id = $1 AND key = $2`,
      [userId, key, STALE_AFTER]
    );
    const row = rows[0];
    if (!row) continue; // cleanup deleted it between the two queries; try again

    if (row.request_hash !== hash) return { kind: "mismatch" };
    if (row.status === "completed") {
      return { kind: "replay", code: row.response_code, body: row.response_body };
    }

    // 3. in_progress: either genuinely running, or abandoned by a crashed request.
    if (row.stale) {
      const take = await pool.query(
        `UPDATE idempotency_keys SET locked_at = now()
         WHERE user_id = $1 AND key = $2 AND status = 'in_progress'
           AND locked_at < now() - $3::interval`,
        [userId, key, STALE_AFTER]
      );
      if (take.rowCount === 1) return { kind: "owned" }; // only one taker can win
    }
    return { kind: "in_flight" };
  }
  return { kind: "in_flight" };
}

const complete = (pool: Pool, userId: string, key: string, r: Result) =>
  pool.query(
    `UPDATE idempotency_keys
     SET status = 'completed', response_code = $3, response_body = $4::jsonb
     WHERE user_id = $1 AND key = $2`,
    [userId, key, r.status, JSON.stringify(r.body)]
  );

const release = (pool: Pool, userId: string, key: string) =>
  pool.query(
    `DELETE FROM idempotency_keys
     WHERE user_id = $1 AND key = $2 AND status = 'in_progress'`,
    [userId, key]
  );

export function idempotent(
  pool: Pool,
  handler: (req: Request) => Promise<Result>
): RequestHandler {
  return async (req, res, next) => {
    const key = req.header("Idempotency-Key");
    if (!key || !KEY_RE.test(key)) {
      return res.status(400).json({ error: "Missing or invalid Idempotency-Key header" });
    }

    const userId = (req as any).user.id as string; // set by your auth middleware
    const hash = hashRequest(req);

    try {
      const state = await claim(pool, userId, key, hash);

      if (state.kind === "mismatch") {
        return res.status(422).json({ error: "Idempotency-Key was already used with a different request" });
      }
      if (state.kind === "in_flight") {
        res.set("Retry-After", "2");
        return res.status(409).json({ error: "A request with this Idempotency-Key is still in progress" });
      }
      if (state.kind === "replay") {
        res.set("Idempotent-Replayed", "true");
        return res.status(state.code).json(state.body);
      }

      // We own the key. Do the real work.
      let result: Result;
      try {
        result = await handler(req);
      } catch (err) {
        await release(pool, userId, key).catch(() => {}); // let the client retry
        return next(err);
      }

      if (result.status >= 500) {
        await release(pool, userId, key).catch(() => {});
      } else {
        await complete(pool, userId, key, result);
      }
      return res.status(result.status).json(result.body);
    } catch (err) {
      return next(err);
    }
  };
}
```

Usage:

```ts
app.post(
  "/api/orders",
  requireAuth,
  express.json(),
  idempotent(pool, async (req) => {
    const order = await createOrder((req as any).user.id, req.body);
    return { status: 201, body: order };
  })
