Your plan assumes three things I can't see confirmed, and each can cause duplicate charges or a stuck breaker if it doesn't hold:

1. **Key retention.** If a payment can sit in retries or behind an open breaker longer than the bank keeps idempotency keys, a resend with the same key may be processed as a new charge.
2. **Breaker parameters.** Threshold, reset timeout, and half-open behavior need values. I've proposed defaults, but they're guesses until you've seen your traffic.
3. **Persist before send.** The same key after a crash only works if the payment record exists before the first bank call.

The wrapper therefore requires the retention window as config with no default, checks the key's age before every send, and calls a store hook that durably records the first send.

```python
import random
import threading
import time
from collections import deque
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Optional, Protocol

OP = "charge"
RETRYABLE = {"timeout", "conn_error", "server_error", "rate_limited"}
AMBIGUOUS = {"timeout", "conn_error", "server_error"}  # bank may have processed it


@dataclass(frozen=True)
class BankCallConfig:
    key_retention: timedelta                      # from the bank's docs; REQUIRED
    key_safety_margin: timedelta = timedelta(hours=1)
    # retries
    max_attempts: int = 4
    base_delay: float = 0.2
    max_delay: float = 5.0
    attempt_timeout: float = 3.0
    call_deadline: float = 20.0                   # whole retry loop, per call
    # breaker (starting defaults, tune from your metrics)
    window_size: int = 20
    min_calls: int = 10
    failure_ratio: float = 0.5
    open_seconds: float = 15.0                    # keep short: slow reset = errors after recovery
    half_open_probes: int = 3

    def __post_init__(self):
        usable = (self.key_retention - self.key_safety_margin).total_seconds()
        if usable <= 0:
            raise ValueError("key_safety_margin must be smaller than key_retention")
        if self.call_deadline >= usable:
            raise ValueError("call_deadline must be well under the key retention window")
        if self.attempt_timeout > self.call_deadline:
            raise ValueError("attempt_timeout cannot exceed call_deadline")


class AttemptStore(Protocol):
    def get_first_sent_at(self, payment_id: str, generation: int) -> Optional[datetime]:
        """UTC time the first request with this key may have been sent, or None."""

    def mark_first_send(self, payment_id: str, generation: int) -> datetime:
        """Durably record the first send BEFORE it happens. First writer wins;
        returns the stored timestamp. Must raise if the payment row doesn't exist."""


class PaymentNotPersisted(Exception): ...
class BankClientError(Exception): ...          # non-retryable 4xx: our bug, not the bank's


class KeyWindowExpired(Exception):
    """Key may no longer be honoured. Do NOT resend. Reconcile with the bank instead."""


class BankCallFailed(Exception):
    def __init__(self, reason, unknown_outcome, attempts):
        super().__init__(f"{reason} (attempts={attempts}, unknown_outcome={unknown_outcome})")
        self.reason, self.unknown_outcome, self.attempts = reason, unknown_outcome, attempts


class CircuitBreaker:
    def __init__(self, cfg: BankCallConfig, clock=time.monotonic):
        self._cfg, self._clock = cfg, clock
        self._lock = threading.Lock()
        self._state = "closed"
        self._results = deque(maxlen=cfg.window_size)
        self._opened_at = 0.0
        self._probes_started = 0
        self._probe_successes = 0
        for s in ("closed", "open", "half_open"):
            BREAKER_STATE.labels(s).set(1 if s == "closed" else 0)

    def _set(self, new):
        if new == self._state:
            return
        BREAKER_TRANSITIONS.labels(self._state, new).inc()
        for s in ("closed", "open", "half_open"):
            BREAKER_STATE.labels(s).set(1 if s == new else 0)
        self._state = new

    def _trip(self):
        self._opened_at = self._clock()
