async function issueResetToken({ email, ip, userAgent }) {
  const client = await pool.connect();
  let rawToken;
  let user;

  try {
    await client.query('BEGIN');

    const { rows } = await client.query(
      'SELECT id, email, first_name FROM users WHERE lower(email) = $1 LIMIT 1',
      [email]
    );
    user = rows[0];
    if (!user) {
      await client.query('ROLLBACK');
      return;
    }

    // Per-account throttle, so the endpoint can't be used to email-bomb a user.
    const { rows: recent } = await client.query(
      `SELECT count(*)::int AS n
         FROM password_reset_tokens
        WHERE user_id = $1 AND created_at > now() - interval '1 hour'`,
      [user.id]
    );
    if (recent[0].n >= MAX_ACTIVE_REQUESTS_PER_HOUR) {
      await client.query('ROLLBACK');
      return;
    }

    // Invalidate earlier outstanding tokens: only the newest link works.
    await client.query(
      `UPDATE password_reset_tokens
          SET used_at = now()
        WHERE user_id = $1 AND used_at IS NULL AND expires_at > now()`,
      [user.id]
    );

    rawToken = crypto.randomBytes(32).toString('base64url');

    await client.query(
      `INSERT INTO password_reset_tokens
         (user_id, token_hash, expires_at, requested_ip, user_agent)
       VALUES ($1, $2, now() + make_interval(mins => $3), $4, $5)`,
      [user.id, sha256Hex(rawToken), TOKEN_TTL_MINUTES, ip ?? null, userAgent]
    );

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }

  // Send after commit. If sending fails, the token is harmless and expires on its own.
  const resetUrl = `${process.env.APP_BASE_URL}/reset-password?token=${rawToken}`;

  await sendPasswordResetEmail({
    to: user.email,
    firstName: user.first_name,
    resetUrl,
    expiryMinutes: TOKEN_TTL_MINUTES,
    requestedAt: new Date(),
  });
}
