export async function savePragraph(req: Request, res: Response) {
  const { id } = req.params;
  const { content, base_version } = req.body ?? {};
  const userId = req.user.id; // assumes auth middleware has already run

  // --- Validation ---
  if (!Number.isInteger(base_version) || base_version < 1) {
    return res.status(400).json({
      error: { code: "missing_base_version", message: "base_version is required and must be a positive integer." },
    });
  }
  if (typeof content !== "string" || content.length > MAX_CONTENT_LENGTH) {
    return res.status(400).json({
      error: { code: "invalid_content", message: "content must be a string within the size limit." },
    });
  }

  // --- Atomic compare-and-set ---
  const updated = await pool.query(
    `UPDATE paragraphs
        SET content = $1,
            version = version + 1,
            updated_at = now(),
            updated_by = $4
      WHERE id = $2 AND version = $3
  RETURNING id, content, version, updated_at, updated_by`,
    [content, id, base_version, userId]
  );
  if (updated.rowCount === 1) {
    return res.status(200).json(updated.rows[0]);
  }

