  // error): the server already holds exactly what the client sent.
  if (row.content === content && row.updated_by === userId) {
    return res.status(200).json(row);
  }

  return res.status(409).json({
    error: {
      code: "version_conflict",
      message: "This paragraph was changed by someone else since you loaded it.",
    },
    paragraph_id: id,
    submitted: { base_version, content },
    current: {
      version: row.version,
      content: row.content,
      updated_at: row.updated_at,
      updated_by: row.updated_by,
