Here's the hook. It assumes React with TypeScript, the `drafts` helper, and the `SaveStatus` type from the indicator. The server save is optional, so you can ship local-only first and add it later without changing the call sites.

```tsx
import { useCallback, useEffect, useRef, useState } from "react";
import { clearDraft, loadDraft, saveDraft, type Draft } from "./drafts";
import type { SaveStatus } from "./SaveIndicator";

type Revision = string | number | null | undefined;

export interface UseAutosaveOptions {
  docId: string;
  content: string;
  /** Server revision that `content` was loaded from. */
  baseRevision?: Revision;
  intervalMs?: number;
  enabled?: boolean;
  /** Optional. Should throw/reject on failure. */
  saveToServer?: (
    content: string,
    baseRevision: Revision
  ) => Promise<{ revision?: Revision } | void>;
}

export function useAutosave({
  docId,
  content,
  baseRevision,
  intervalMs = 5000,
  enabled = true,
  saveToServer,
}: UseAutosaveOptions) {
  const [status, setStatus] = useState<SaveStatus>("idle");
  const [savedAt, setSavedAt] = useState<number | null>(null);
  const [target, setTarget] = useState<"local" | "server">(
    saveToServer ? "server" : "local"
  );

  // Draft found on mount that differs from the loaded content.
  const [pendingDraft, setPendingDraft] = useState<Draft | null>(() => {
    const d = loadDraft(docId);
    return d && d.content !== content ? d : null;
  });

  // Refs hold the latest values so the interval never has to be reset.
  const contentRef = useRef(content);
  contentRef.current = content;
  const saveToServerRef = useRef(saveToServer);
  saveToServerRef.current = saveToServer;
  const pendingRef = useRef(pendingDraft);
  pendingRef.current = pendingDraft;
  const revisionRef = useRef<Revision>(baseRevision);
  useEffect(() => {
    revisionRef.current = baseRevision;
  }, [baseRevision]);

  // The initial content is assumed to match what's on the server.
  const lastLocalRef = useRef(content);
  const lastServerRef = useRef(content);
  const inFlightRef = useRef(false);

  const saveLocal = useCallback((): boolean => {
    const latest = contentRef.current;
    if (latest === lastLocalRef.current) return true;
    const ok = saveDraft(docId, latest, revisionRef.current);
    if (ok) lastLocalRef.current = latest;
    return ok;
  }, [docId]);

  const tick = useCallback(async () => {
    // While a restore decision is pending, don't overwrite the stored draft.
    if (!enabled || pendingRef.current) return;

    const save = saveToServerRef.current;
    const latest = contentRef.current;
    const localChanged = latest !== lastLocalRef.current;
    const serverChanged = !!save && latest !== lastServerRef.current;
    if (!localChanged && !serverChanged) return;

    if (localChanged) {
      const ok = saveLocal();
      if (!serverChanged) {
        setTarget("local");
        setStatus(ok ? "saved" : "error");
        if (ok) setSavedAt(Date.now());
        return;
      }
      // If the local write failed, still try the server below.
    }

    if (!save || inFlightRef.current) return;
    inFlightRef.current = true;
    setStatus("saving");
    try {
      const res = await save(latest, revisionRef.current);
      lastServerRef.current = latest;
      if (res && res.revision !== undefined) revisionRef.current = res.revision;

      if (contentRef.current === latest) {
        // Only clear the draft if the user hasn't typed since this save began.
        clearDraft(docId);
        lastLocalRef.current = latest;
        setStatus("saved");
      } else {
        setStatus("dirty"); // next tick picks up the newer edits
      }
      setTarget("server");
      setSavedAt(Date.now());
    } catch (err) {
      console.warn(`Server save failed for ${docId}`, err);
      setTarget("server");
      setStatus("error"); // retried on the next tick
    } finally {
      inFlightRef.current = false;
    }
  }, [docId, enabled, saveLocal]);

  // Mark dirty immediately on edit, rather than waiting for the next tick.
  useEffect(() => {
    const persisted = saveToServerRef.current
      ? lastServerRef.current
      : lastLocalRef.current;
    setStatus((s) => {
      if (s === "saving" || s === "error") return s;
      if (content !== persisted) return "dirty";
      return s === "dirty" ? "idle" : s;
    });
  }, [content]);

  // The autosave loop.
  useEffect(() => {
    if (!enabled) return;
    const id = setInterval(() => void tick(), intervalMs);
    return () => clearInterval(id);
  }, [enabled, intervalMs, tick]);

  // Flush the local draft when the tab is hidden or closed, and on unmount.
  useEffect(() => {
    const flush = () => {
      if (enabled && !pendingRef.current) saveLocal();
    };
    const onVisibility = () => {
      if (document.visibilityState === "hidden") flush();
    };
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", flush);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", flush);
      flush();
    };
  }, [enabled, saveLocal]);

  /** Returns the draft's content so the caller can put it in the editor. */
  const restoreDraft = useCallback((): string | null => {
    const d = pendingRef.current;
    setPendingDraft(null);
    return d ? d.content : null;
  }, []);

  const discardDraft = useCallback(() => {
    clearDraft(docId);
    setPendingDraft(null);
  }, [docId]);

  return {
    status,
    savedAt,
    target,
    pendingDraft,
    restoreDraft,
    discardDraft,
    /** Save immediately, e.g. from a Ctrl+S handler. */
    saveNow: tick,
  };
}
```

