import { useState } from "react";

export function PhoneVerificationBanner({ user }) {
  const KEY = "phone_banner_dismissed";
  const [dismissed, setDismissed] = useState(
    () => sessionStorage.getItem(KEY) === "1"
  );

  if (!user || user.phoneVerifiedAt || dismissed) return null;

  return (
    <div role="region" aria-label="Phone verification" className="phone-banner">
      <p className="phone-banner__text">
        Verify your phone number to make your first payment. It takes less than a minute.
      </p>
      <a href="/verify-phone" className="phone-banner__cta">Verify now</a>
      <button
        type="button"
        aria-label="Dismiss"
        onClick={() => {
          sessionStorage.setItem(KEY, "1");
          setDismissed(true);
        }}
      >
        ×
      </button>
    </div>
  );
}
```

**Design choices**

- **Dismissal lasts one session, not forever.** Verification is still required before payment, so users shouldn't be able to hide the reminder permanently. It comes back next visit.
- **Copy states the reason.** "To make your first payment" explains why you're asking, which tends to work better than a generic "verify your account."
- **Hidden on the verification page**, where it would just be noise.
- **It's only a nudge.** The real enforcement has to be a server-side check at payment time, never just the banner.
- **Analytics hook.** The `data-analytics-event` attribute is there so you can track banner clicks. Along with verification completion rate, that tells you whether the new flow is recovering the signups you lost.

