import React from "react";
import "./SignupProgress.css";

type SignupProgressProps = {
  /** Current step, 1-indexed (1–4) */
  currentStep: number;
  /** Optional custom labels; must match the number of steps */
  steps?: string[];
};

const DEFAULT_STEPS = ["Account", "Profile", "Verify", "Done"];

export function SignupProgress({
  currentStep,
  steps = DEFAULT_STEPS,
}: SignupProgressProps) {
  const total = steps.length;
  const clamped = Math.min(Math.max(currentStep, 1), total);

  return (
    <nav aria-label="Signup progress" className="signup-progress">
      <p className="signup-progress__summary" aria-live="polite">
        Step {clamped} of {total}: {steps[clamped - 1]}
      </p>

      <ol className="signup-progress__list">
        {steps.map((label, i) => {
          const stepNumber = i + 1;
          const status =
            stepNumber < clamped
              ? "complete"
              : stepNumber === clamped
              ? "current"
              : "upcoming";

          return (
            <li
              key={label}
              className={`signup-progress__step signup-progress__step--${status}`}
              aria-current={status === "current" ? "step" : undefined}
            >
              <span className="signup-progress__marker" aria-hidden="true">
                {status === "complete" ? "✓" : stepNumber}
              </span>
              <span className="signup-progress__label">
                {label}
                {status === "complete" && (
                  <span className="visually-hidden"> (completed)</span>
                )}
              </span>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
```

