This loader builds on `calculateInSampleSize` and `BitmapMemoryCache` from earlier. I switched from file paths to `Uri`s, since `decodeFile` won't work on content URIs under scoped storage. If your gallery really uses plain file paths, `Uri.fromFile(file)` works too.

```kotlin
import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.net.Uri
import android.view.View
import android.widget.ImageView
import androidx.core.view.doOnLayout
import androidx.exifinterface.media.ExifInterface
import kotlinx.coroutines.*
import kotlin.coroutines.resume

class ImageLoader(
    context: Context,
    private val cache: BitmapMemoryCache,
    private val config: Bitmap.Config = Bitmap.Config.RGB_565
) {
    private val resolver = context.applicationContext.contentResolver

    // Caps concurrent decodes so fast scrolling can't pile up large allocations.
    private val decodeDispatcher = Dispatchers.IO.limitedParallelism(2)

    /**
     * Loads [uri] into [view], downsampled to the target size.
     * Pass [scope] as the fragment's viewLifecycleOwner.lifecycleScope.
     * If targetWidth/Height are 0, waits for the view to be laid out and uses its size.
     */
    fun load(
        view: ImageView,
        uri: Uri,
        scope: CoroutineScope,
        placeholderRes: Int = 0,
        targetWidth: Int = 0,
        targetHeight: Int = 0
    ) {
        cancel(view) // a recycled view must drop its previous request

        if (placeholderRes != 0) view.setImageResource(placeholderRes) else view.setImageDrawable(null)

        val job = scope.launch {
            if (targetWidth <= 0 || targetHeight <= 0) view.awaitLayout()
            val w = if (targetWidth > 0) targetWidth else view.width
            val h = if (targetHeight > 0) targetHeight else view.height

            // Cancelled jobs throw at the withContext boundary, so a stale
            // result can never be set on a view that has been rebound.
            val bitmap = loadBitmap(uri, w, h)
            if (bitmap != null) view.setImageBitmap(bitmap)
        }
        view.setTag(R.id.image_loader_job, job)
    }

    fun cancel(view: ImageView) {
        (view.getTag(R.id.image_loader_job) as? Job)?.cancel()
        view.setTag(R.id.image_loader_job, null)
    }

    suspend fun loadBitmap(uri: Uri, w: Int, h: Int): Bitmap? {
        val key = BitmapMemoryCache.key(uri.toString(), w, h)
        cache.get(key)?.let { return it }

        val bitmap = withContext(decodeDispatcher) { decode(uri, w, h) } ?: return null
        cache.put(key, bitmap)
        return bitmap
    }

    private suspend fun decode(uri: Uri, reqW: Int, reqH: Int): Bitmap? {
        try {
            val rotation = readRotation(uri)
            currentCoroutineContext().ensureActive()

            // Pass 1: bounds only, no pixel allocation.
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

            // For 90/270 rotations the displayed width is the stored height.
            val swap = rotation == 90 || rotation == 270
            val srcW = if (swap) bounds.outHeight else bounds.outWidth
            val srcH = if (swap) bounds.outWidth else bounds.outHeight

            currentCoroutineContext().ensureActive()

            // Pass 2: decode downsampled.
            val opts = BitmapFactory.Options().apply {
                inSampleSize = calculateInSampleSize(srcW, srcH, reqW, reqH)
                inPreferredConfig = config
            }
            val decoded = resolver.openInputStream(uri)?.use {
                BitmapFactory.decodeStream(it, null, opts)
            } ?: return null

            return applyRotation(decoded, rotation)
        } catch (e: OutOfMemoryError) {
            // Last-resort backstop, not a fix: free the cache and skip this image
            // rather than crash. If this fires often, the budgets are too high.
            cache.evictAll()
            return null
        }
    }

    private fun readRotation(uri: Uri): Int = try {
        resolver.openInputStream(uri)?.use { stream ->
            when (ExifInterface(stream).getAttributeInt(
                ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL
            )) {
                ExifInterface.ORIENTATION_ROTATE_90 -> 90
                ExifInterface.ORIENTATION_ROTATE_180 -> 180
                ExifInterface.ORIENTATION_ROTATE_270 -> 270
                else -> 0 // flips/transposes ignored for simplicity
            }
        } ?: 0
    } catch (e: Exception) { 0 }

    private fun applyRotation(src: Bitmap, degrees: Int): Bitmap {
        if (degrees == 0) return src
        val m = Matrix().apply { postRotate(degrees.toFloat()) }
        val rotated = Bitmap.createBitmap(src, 0, 0, src.width, src.height, m, true)
        // Safe to recycle: `src` was just decoded here and was never shared or cached.
        if (rotated !== src) src.recycle()
        return rotated
    }

    private suspend fun View.awaitLayout() {
        if (isLaidOut && width > 0 && height > 0) return
        suspendCancellableCoroutine { cont ->
            doOnLayout { if (cont.isActive) cont.resume(Unit) }
        }
    }
}
```

