One thing to flag: building this by hand assumes it's the better route, and that may not hold. Coil and Glide already handle downsampling, bounded caches, bitmap pooling, request deduplication, and lifecycle-aware cancellation. For an OOM regression, missing one of those edge cases is the main risk. If you have a reason to stay custom (no new dependencies, unusual sources, a hotfix you can fully audit), the version below covers the essentials.

```kotlin
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.view.View
import android.view.ViewTreeObserver
import android.widget.ImageView
import androidx.annotation.DrawableRes
import androidx.exifinterface.media.ExifInterface
import kotlinx.coroutines.*
import java.util.WeakHashMap
import kotlin.coroutines.resume

/**
 * Create one per screen, e.g. with viewLifecycleOwner.lifecycleScope,
 * and share the app-level cache. Call from the main thread only.
 */
class ImageLoader(
    private val cache: BitmapMemoryCache,
    private val scope: CoroutineScope
) {
    // Caps concurrent decodes so fast scrolling can't spike memory.
    private val decodeDispatcher = Dispatchers.IO.limitedParallelism(2)
    private val jobs = WeakHashMap<ImageView, Job>()

    fun load(view: ImageView, path: String, @DrawableRes placeholder: Int = 0) {
        cancel(view)
        if (placeholder != 0) view.setImageResource(placeholder) else view.setImageDrawable(null)

        jobs[view] = scope.launch(Dispatchers.Main.immediate) {
            val (w, h) = view.awaitSize()
            val bmp = loadBitmap(path, w, h) ?: return@launch
            view.setImageBitmap(bmp)
        }
    }

    fun cancel(view: ImageView) {
        jobs.remove(view)?.cancel()
    }

    private suspend fun loadBitmap(path: String, w: Int, h: Int): Bitmap? {
        val key = BitmapMemoryCache.key(path, w, h)
        cache.get(key)?.let { return it }

        // If the job was cancelled while queued, withContext throws before decoding starts.
        val bmp = withContext(decodeDispatcher) { decode(path, w, h) } ?: return null
        cache.put(key, bmp)
        return bmp
    }

    private fun decode(path: String, reqW: Int, reqH: Int): Bitmap? {
        val rotation = exifRotation(path)

        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(path, bounds)
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

        val swap = rotation % 180 != 0
        val srcW = if (swap) bounds.outHeight else bounds.outWidth
        val srcH = if (swap) bounds.outWidth else bounds.outHeight

        val opts = BitmapFactory.Options().apply {
            inSampleSize = calculateInSampleSize(srcW, srcH, reqW, reqH)
            inPreferredConfig = Bitmap.Config.RGB_565
        }

        val decoded = try {
            BitmapFactory.decodeFile(path, opts)
        } catch (e: OutOfMemoryError) {
            cache.evictAll() // free what we can; the view just keeps its placeholder
            return null
        } ?: return null

        if (rotation == 0) return decoded
        return try {
            val m = Matrix().apply { postRotate(rotation.toFloat()) }
            val rotated = Bitmap.createBitmap(decoded, 0, 0, decoded.width, decoded.height, m, true)
            if (rotated !== decoded) decoded.recycle() // safe: never cached or shown
            rotated
        } catch (e: OutOfMemoryError) {
            cache.evictAll()
            null
        }
    }

    private fun exifRotation(path: String): Int = try {
        when (ExifInterface(path).getAttributeInt(
            ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL
        )) {
            ExifInterface.ORIENTATION_ROTATE_90 -> 90
            ExifInterface.ORIENTATION_ROTATE_180 -> 180
            ExifInterface.ORIENTATION_ROTATE_270 -> 270
            else -> 0
        }
    } catch (e: Exception) { 0 }
}

/** Returns immediately if the view is laid out, otherwise waits for the first pass with a real size. */
private suspend fun View.awaitSize(): Pair<Int, Int> {
    if (width > 0 && height > 0) return width to height
    return suspendCancellableCoroutine { cont ->
        val vto = viewTreeObserver
        val listener = object : ViewTreeObserver.OnPreDrawListener {
            override fun onPreDraw(): Boolean {
                if (width > 0 && height > 0) {
                    if (vto.isAlive) vto.removeOnPreDrawListener(this)
                    cont.resume(width to height)
                }
                return true
            }
        }
        vto.addOnPreDrawListener(listener)
        cont.invokeOnCancellation { if (vto.isAlive) vto.removeOnPreDrawListener(listener) }
    }
}
```

