Here's a logger that tracks the current screen via lifecycle callbacks and writes synchronously, since the process may die right after the handler runs.

```kotlin
import android.app.Activity
import android.app.Application
import android.os.Build
import android.os.Bundle
import android.util.Log
import androidx.fragment.app.Fragment
import androidx.fragment.app.FragmentActivity
import androidx.fragment.app.FragmentManager
import java.io.File
import java.io.PrintWriter
import java.io.StringWriter
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

object CrashLogger {

    private const val TAG = "CrashLogger"
    private const val MAX_LOG_BYTES = 512 * 1024L

    @Volatile private var currentScreen: String = "unknown"
    private var logFile: File? = null
    private var appVersion: String = "unknown"

    fun init(app: Application) {
        logFile = File(app.filesDir, "crash_log.txt")
        appVersion = try {
            val info = app.packageManager.getPackageInfo(app.packageName, 0)
            "${info.versionName} (${info.longVersionCode})"
        } catch (e: Exception) {
            "unknown"
        }

        app.registerActivityLifecycleCallbacks(object : Application.ActivityLifecycleCallbacks {
            override fun onActivityResumed(activity: Activity) {
                currentScreen = activity::class.java.simpleName
            }

            override fun onActivityCreated(activity: Activity, savedInstanceState: Bundle?) {
                (activity as? FragmentActivity)?.supportFragmentManager
                    ?.registerFragmentLifecycleCallbacks(fragmentCallbacks, true)
            }

            override fun onActivityStarted(activity: Activity) {}
            override fun onActivityPaused(activity: Activity) {}
            override fun onActivityStopped(activity: Activity) {}
            override fun onActivitySaveInstanceState(activity: Activity, outState: Bundle) {}
            override fun onActivityDestroyed(activity: Activity) {}
        })
    }

    private val fragmentCallbacks = object : FragmentManager.FragmentLifecycleCallbacks() {
        override fun onFragmentResumed(fm: FragmentManager, f: Fragment) {
            // Skip container/dialog-less wrappers if you like; this keeps it simple
            currentScreen = f::class.java.simpleName
        }
    }

    /** Call manually for Compose destinations or custom navigation. */
    fun setScreen(name: String) {
        currentScreen = name
    }

    fun getCurrentScreen(): String = currentScreen

    /** Never throws — it runs while the app is already crashing. */
    fun log(thread: Thread, throwable: Throwable) {
        try {
            val timestamp = SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.US).format(Date())
            val stack = StringWriter().also { throwable.printStackTrace(PrintWriter(it)) }.toString()

            val entry = buildString {
                appendLine("==== CRASH $timestamp ====")
                appendLine("Screen:  $currentScreen")
                appendLine("Device:  ${Build.MANUFACTURER} ${Build.MODEL}")
                appendLine("Android: ${Build.VERSION.RELEASE} (API ${Build.VERSION.SDK_INT})")
                appendLine("App:     $appVersion")
                appendLine("Thread:  ${thread.name}")
                appendLine(stack)
            }

            Log.e(TAG, entry)

            logFile?.let { file ->
                if (file.exists() && file.length() > MAX_LOG_BYTES) file.delete()
                file.appendText(entry)  // synchronous on purpose
            }
        } catch (t: Throwable) {
            Log.e(TAG, "Failed to write crash log", t)
        }
    }
}
```

Install it in your `Application` class:

```kotlin
